    currentHookIndex++;
    return pair;
  }
  pair = [initialState, setState];  // first render: create the slot
  function setState(nextState) {
    pair[0] = nextState;
    updateDOM();
  }
  componentHooks[currentHookIndex] = pair;
  currentHookIndex++;
  return pair;
}

function Cond({ flag }) {
  const [x] = useState('x');     // slot 0
  if (flag) {
    const [y] = useState('y');   // slot 1, only when flag
  }
  const [z] = useState('z');     // slot 1 or 2
  return <i>{x}{z}</i>;
}

